From e76928c438ab66526520e1d5ba36753a518a29a0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:42:51 +0100
Subject: [PATCH] shell: give screens a grid position that follows their
 arrangement

The Manage Panels and Desktops model listed screens in screen pool
order, so the window couldn't show them the way they're arranged. Each
screen now gets a row and column from its geometry, disconnected below.

BUG: 477122
---
 shell/shellcontainmentconfig.cpp | 67 ++++++++++++++++++++++++++++++++
 shell/shellcontainmentconfig.h   | 13 +++++++
 2 files changed, 80 insertions(+)

diff --git a/shell/shellcontainmentconfig.cpp b/shell/shellcontainmentconfig.cpp
index 5bc79a9128..c0e6a8ccb9 100644
--- a/shell/shellcontainmentconfig.cpp
+++ b/shell/shellcontainmentconfig.cpp
@@ -37,6 +37,7 @@ ScreenPoolModel::ScreenPoolModel(ShellCorona *corona, QObject *parent)

     connect(m_corona, &Plasma::Corona::screenAdded, m_reloadTimer, static_cast<void (QTimer::*)()>(&QTimer::start));
     connect(m_corona, &Plasma::Corona::screenRemoved, m_reloadTimer, static_cast<void (QTimer::*)()>(&QTimer::start));
+    connect(m_corona, &Plasma::Corona::screenGeometryChanged, m_reloadTimer, static_cast<void (QTimer::*)()>(&QTimer::start));
 }

 ScreenPoolModel::~ScreenPoolModel() = default;
@@ -60,6 +61,10 @@ QVariant ScreenPoolModel::data(const QModelIndex &index, int role) const
         return d.primary;
     case EnabledRole:
         return d.enabled;
+    case LayoutRowRole:
+        return d.row;
+    case LayoutColumnRole:
+        return d.column;
     }
     return {};
 }
@@ -80,10 +85,17 @@ QHash<int, QByteArray> ScreenPoolModel::roleNames() const
         {ContainmentsRole, QByteArrayLiteral("containments")},
         {EnabledRole, QByteArrayLiteral("isEnabled")},
         {PrimaryRole, QByteArrayLiteral("isPrimary")},
+        {LayoutRowRole, QByteArrayLiteral("layoutRow")},
+        {LayoutColumnRole, QByteArrayLiteral("layoutColumn")},
     });
     return roles;
 }

+int ScreenPoolModel::layoutColumns() const
+{
+    return m_layoutColumns;
+}
+
 void ScreenPoolModel::load()
 {
     beginResetModel();
@@ -116,6 +128,7 @@ void ScreenPoolModel::load()
         }
         d.primary = knownId == 0;
         d.enabled = true;
+        d.geometry = screen->geometry();

         auto *conts = new ShellContainmentModel(m_corona, knownId, this);
         conts->load();
@@ -130,6 +143,45 @@ void ScreenPoolModel::load()
         ++knownId;
     }

+    // Lay out the connected screens on a grid that follows their arrangement: each one
+    // goes after all the screens that are entirely to its left, and below all the ones above it
+    QList<Data *> connected;
+    for (Data &d : m_screens) {
+        connected.push_back(&d);
+    }
+    std::ranges::sort(connected, {}, [](const Data *d) {
+        return d->geometry.x();
+    });
+    for (qsizetype i = 0; i < connected.size(); ++i) {
+        for (qsizetype j = 0; j < i; ++j) {
+            if (connected[j]->geometry.x() + connected[j]->geometry.width() <= connected[i]->geometry.x()) {
+                connected[i]->column = std::max(connected[i]->column, connected[j]->column + 1);
+            }
+        }
+    }
+    std::ranges::sort(connected, {}, [](const Data *d) {
+        return d->geometry.y();
+    });
+    for (qsizetype i = 0; i < connected.size(); ++i) {
+        for (qsizetype j = 0; j < i; ++j) {
+            if (connected[j]->geometry.y() + connected[j]->geometry.height() <= connected[i]->geometry.y()) {
+                connected[i]->row = std::max(connected[i]->row, connected[j]->row + 1);
+            }
+        }
+    }
+    // Overlapping screens would end up in the same cell
+    QSet<std::pair<int, int>> usedCells;
+    int columns = 1;
+    int rows = 0;
+    for (Data *d : std::as_const(connected)) {
+        while (usedCells.contains({d->row, d->column})) {
+            ++d->column;
+        }
+        usedCells.insert({d->row, d->column});
+        columns = std::max(columns, d->column + 1);
+        rows = std::max(rows, d->row + 1);
+    }
+
     QList sortedIds = unknownScreenIds.values();
     std::ranges::sort(sortedIds);
     for (int id : sortedIds) {
@@ -138,13 +190,28 @@ void ScreenPoolModel::load()
         d.name = i18n("Disconnected Screen %1", id + 1);
         d.primary = id == 0;
         d.enabled = false;
+        // Disconnected screens go in rows below the connected ones
+        const int disconnectedIndex = m_screens.size() - connected.size();
+        const int disconnectedColumns = std::max(columns, 2);
+        d.row = rows + disconnectedIndex / disconnectedColumns;
+        d.column = disconnectedIndex % disconnectedColumns;

         auto *conts = new ShellContainmentModel(m_corona, id, this);
         conts->load();
         m_containments.push_back(conts);
         m_screens.push_back(d);
     }
+
+    int layoutColumns = 1;
+    for (const Data &d : std::as_const(m_screens)) {
+        layoutColumns = std::max(layoutColumns, d.column + 1);
+    }
     endResetModel();
+
+    if (m_layoutColumns != layoutColumns) {
+        m_layoutColumns = layoutColumns;
+        Q_EMIT layoutColumnsChanged();
+    }
 }

 void ScreenPoolModel::remove(int screenId)
diff --git a/shell/shellcontainmentconfig.h b/shell/shellcontainmentconfig.h
index 5a5378aec5..8a7c707e57 100644
--- a/shell/shellcontainmentconfig.h
+++ b/shell/shellcontainmentconfig.h
@@ -28,6 +28,8 @@ class ScreenPoolModel : public QAbstractListModel
 {
     Q_OBJECT

+    Q_PROPERTY(int layoutColumns READ layoutColumns NOTIFY layoutColumnsChanged)
+
 public:
     enum ScreenPoolModelRoles {
         ScreenIdRole = Qt::UserRole + 1,
@@ -35,6 +37,8 @@ public:
         ContainmentsRole,
         PrimaryRole,
         EnabledRole,
+        LayoutRowRole,
+        LayoutColumnRole,
     };

 public:
@@ -45,10 +49,15 @@ public:
     int rowCount(const QModelIndex &parent = QModelIndex()) const override;
     QHash<int, QByteArray> roleNames() const override;

+    int layoutColumns() const;
+
 public Q_SLOTS:
     void load();
     void remove(int screenId);

+Q_SIGNALS:
+    void layoutColumnsChanged();
+
 private:
     ShellCorona *const m_corona;
     struct Data {
@@ -56,8 +65,12 @@ private:
         QString name;
         bool primary;
         bool enabled;
+        QRect geometry;
+        int row = 0;
+        int column = 0;
     };
     QTimer *m_reloadTimer = nullptr;
+    int m_layoutColumns = 1;
     QList<Data> m_screens;
     QList<ShellContainmentModel *> m_containments;
 };
